/**
 * @name Code injection via exec with taint flow
 * @description Using exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/exec-taint-flow
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module ExecTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any parameter to a function could be untrusted
    source instanceof DataFlow::ParameterNode or
    // Any attribute access could be untrusted
    source.asExpr() instanceof Attribute
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asExpr().(Name).getId() in ["exec", "eval"] and
      sink = call.getArg(0)
    )
  }
}

module ExecTaintFlow = TaintTracking::Global<ExecTaintConfig>;
import ExecTaintFlow::PathGraph

from ExecTaintFlow::PathNode source, ExecTaintFlow::PathNode sink
where ExecTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Exec with potentially untrusted input from $@.", source.getNode(), "here"
